Loading a dataset

library(dplyr)

buffalo &lt;- read.csv("data/buffalo_kruger.csv.gz") |&gt;
  transmute(
    id   = individual.local.identifier,
    t    = as.POSIXct(timestamp, tz = "UTC"),
    x    = location.long,
    y    = location.lat
  ) |&gt;
  filter(!is.na(x), !is.na(y)) |&gt;
  distinct(id, t, .keep_all = TRUE) |&gt;   # the duplicate fix described above
  arrange(id, t)

glimpse(buffalo)

Task 1 — Prepare the data
An HMM needs regular sampling and contiguous sequences. That is exactly what the bursts from Class 3 give us.

clean &lt;- read.csv("data/buffalo_kruger.csv.gz") |&gt;
  transmute(id = individual.local.identifier,
            t  = as.POSIXct(timestamp, tz = "UTC"),
            x  = location.long, y = location.lat) |&gt;
  filter(!is.na(x), !is.na(y)) |&gt;
  distinct(id, t, .keep_all = TRUE)

trk_hr &lt;- make_track(clean, x, y, t, id = id, crs = 4326) |&gt;
  transform_coords(crs_to = 32736) |&gt;
  nest(data = -id) |&gt;
  mutate(data = lapply(data, \(d) {
    d |&gt; track_resample(rate = hours(1), tolerance = minutes(10)) |&gt;
      filter_min_n_burst(min_n = 3)
  })) |&gt;
  unnest(cols = data)

# Each burst is an independent sequence: that is what moveHMM calls an "ID"
hmm_in &lt;- trk_hr |&gt;
  filter(id %in% c("Cilla", "Toni")) |&gt;
  transmute(ID = paste(id, burst_, sep = "_"), x = x_, y = y_)

pd &lt;- prepData(as.data.frame(hmm_in), type = "UTM", coordNames = c("x", "y"))

summary(pd$step)
#&gt;     Min.  1st Qu.   Median     Mean  3rd Qu.     Max.      NAs 
#&gt;     0.00    39.25   163.72   290.19   381.02 63102.52       28
sum(pd$step == 0, na.rm = TRUE)
#&gt; [1] 9







ImportantTwo things to notice before fitting



Zero step lengths. A gamma distribution has zero density at zero, so any exact zero makes the likelihood infinite. moveHMM handles this with a zero-mass parameter per state — but only if you supply initial values for it, otherwise you get Wrong number of initial parameters -- there should be 6.
A 63 km step. That is the spatial outlier we found in Class 3. An HMM will happily invent a “teleporting” state to accommodate two bad fixes. Remove them.



max(pd$step, na.rm = TRUE)
#&gt; [1] 63102.52
sum(pd$step &gt; 5000, na.rm = TRUE)
#&gt; [1] 2

bad_ids &lt;- unique(pd$ID[which(pd$step &gt; 5000)])
pd &lt;- pd[!(pd$ID %in% bad_ids), ]

nrow(pd)
#&gt; [1] 9264
round(max(pd$step, na.rm = TRUE))
#&gt; [1] 4166

Setup — the cleaned track from Class 3

clean &lt;- read.csv("data/buffalo_kruger.csv.gz") |&gt;
  transmute(id = individual.local.identifier,
            t  = as.POSIXct(timestamp, tz = "UTC"),
            x  = location.long, y = location.lat) |&gt;
  filter(!is.na(x), !is.na(y)) |&gt;
  distinct(id, t, .keep_all = TRUE)

trk &lt;- make_track(clean, x, y, t, id = id, crs = 4326) |&gt;
  transform_coords(crs_to = 32736)

resample_by_id &lt;- function(tr, rate, tol) {
  tr |&gt;
    nest(data = -id) |&gt;
    mutate(data = lapply(data, \(d) {
      d |&gt; track_resample(rate = rate, tolerance = tol) |&gt;
        filter_min_n_burst(min_n = 3)
    })) |&gt;
    unnest(cols = data)
}

trk_hr &lt;- resample_by_id(trk, hours(1), minutes(10))
nrow(trk_hr)
#&gt; [1] 22828

Task 5 — Now try the bats

bat &lt;- read.csv("data/bat_safi.csv.gz") |&gt;
  transmute(id = individual.local.identifier,
            t  = as.POSIXct(timestamp, tz = "UTC"),
            x  = location.long, y = location.lat) |&gt;
  filter(!is.na(x), !is.na(y)) |&gt;
  distinct(id, t, .keep_all = TRUE)

bat_trk &lt;- make_track(bat, x, y, t, id = id, crs = 4326) |&gt;
  transform_coords(crs_to = 32632)     # UTM 32N, Switzerland

bat_trk |&gt;
  summarize_sampling_rate_many(cols = "id", time_unit = "min") |&gt;
  mutate(across(where(is.numeric), \(z) round(z, 1))) |&gt;
  head(8)
